    guide_text_fc81d74c51395819: "每篇文章都标有编辑上次对照线上网站核查的日期。日期由编辑在检查后手动填写，不会随网站重新构建而改变。",
    guide_text_d2871a9838a24e99: "选择阅读指南的语言。译文使用与{name_a}其他页面相同的控件名称。官方名称、标识符和引用的来源原文保留原语言。",
    guide_text_0b1c918dea55487f: "发现错误或遗漏？[关于页面的反馈表单]({link_a})可联系维护人员，无需账户。",
    guide_text_b50e208649012afa: "第1步——打开关联详情",
