    guide_text_0cc284d7559fd468: "在本示例中，如果出现**Update to Parks List of Qualifying Documents for Disability Membership Fee**，选择它旁边的**{control_b}**。记录可用时，[示例关联链接]({link_a})会直接打开该面板。",
    guide_text_016cbce48bd3bea2: "公园规则记录，标题旁有{control_a}链接。",
