    guide_text_b096b7929e479242: "在**{control_a}**中阅读匹配标签和日期。本例中的**{control_b}**和**Matched to the agency's published name**说明了依据。在**{control_c}**下阅读关系：**发布规则**。打开面板中的**{control_d}**，对照官方来源，然后返回。",
    guide_text_ae1bbd19f3ff6c02: "这些证据支持所述关联，并非对合规或不当行为的认定。[记录如何关联]({link_a})解释其他匹配标签。",
