    guide_text_3d2ed81259c40e96: "四种入口，分别用于学习、做事、理解或查阅。",
    guide_text_a08cf344721d119e: "从哪里开始",
    guide_text_a3d77913305af74c: "关于本指南",
    guide_text_38c86e7d74743b49: "{name_a}是非官方的阅读辅助工具。请在官方来源核查每条记录。",
    guide_text_9b8197f3d9d1b528: "关于数据",
    guide_text_611d488100fd45e5: "公共记录能告诉您什么 · {name_a}",
    guide_text_1acba7083479a93a: "{name_a}上的记录证明市政府发布了某项内容。它是否也表明作出了决定，取决于您阅读的记录类型。",
    guide_text_4c6226ecc7a75837: "返回指南",
    guide_text_cf6c27f433c20dcf: "已发布记录能证实政府行动的哪些方面，以及刻意不下结论的部分。",
