    guide_text_8923e6f68ab5aba0: "本文使用的来源",
    guide_text_676699a9a2c0a6ba: "{name_a} Online，由City of New York发布",
    guide_text_4c684d004983949f: "在纽约市议会听证会上作证",
    guide_text_6dec5d244ab8699e: "NYC Rules，市政府规则制定门户",
    guide_text_91c8546ebe5c6e99: "拟议合同公开听证会，Mayor's Office of Contract Services",
