    guide_text_8c6bd74ccca6bb39: "按类型浏览公共记录",
    guide_text_2c7e91949fe059ce: "记录如何关联 · {name_a}",
    guide_text_95b1c09f5051bb30: "{name_a}上两条记录之间的关联，是有明确依据的说法。这里说明其主张、核查方式及界限。",
    guide_text_ba1a082691ee350d: "{name_a}链接两条记录时表示什么、如何检查该说法，以及为何一些明显关系仍未链接。",
    guide_text_d7004a7d79a46dca: "日期与空白的含义 · {name_a}",
    guide_text_77ebe53aa882229d: "记录有几种不同日期，也有几种不同空白。区分它们是稳妥阅读记录的主要方法。",
    guide_text_7d17bd488fb541fc: "如何区分记录上的日期，以及如何阅读空字段而不自行赋予含义。",
    guide_text_c0f2916a9cf53911: "{name_a}如何分类缺失字段",
    guide_text_0a50d115acdd7d58: "标记与历史规律 · {name_a}",
    guide_text_6114a9b5eb0bbe11: "{name_a}上的标记和历史规律说明是统计背景，绝非调查结论。这里说明各项统计什么，以及确切规则的位置。",
    guide_text_924377705beee643: "记录中的计算说明是什么、不是什么，以及各项确切规则的文档位置。",
    guide_text_6bf3fc8ff2388897: "关于页面对标记和背景的解释",
    guide_text_5180d532d56a7e19: "公共采购风险标记，Open Contracting Partnership",
    guide_text_791ca1ebeb18d813: "Opentender廉洁指标",
