    guide_text_c4ed3f217e5f1d95: "查找并缩小记录范围 · {name_a}",
    guide_text_361a0af908a9fa38: "在{name_a}搜索主题，进入所需记录类型的集合，缩小范围、保存链接，并处理无结果情况。",
    guide_text_bdd327c1eb551192: "查找主题、缩小相关集合范围，并保存包含筛选条件的链接。",
    guide_text_3b072d955b2c1aee: "浏览各类记录",
    guide_text_cd844bda587f4a6c: "开始搜索",
    guide_text_d37002b0e29de8f4: "关注搜索 · {name_a}",
    guide_text_ba9c33ecda3b7981: "预览关注会匹配什么，一步创建，然后改变邮件频率、暂停或停止，并了解每项操作的作用。",
    guide_text_cd9c1c2536d837c4: "预览关注，用电子邮件地址创建，并管理或停止更新。",
    guide_text_1584b537f5eb2e7e: "打开提醒",
    guide_text_7bbb744a82034ffe: "关注社区委员会 · {name_a}",
    guide_text_b84b2c660ad6f86a: "选择行政区和委员会编号以关注一个社区委员会，将其与市议会选区区分，并了解匹配内容实际覆盖什么。",
    guide_text_8f0e3b5fed63e6c0: "为一个社区委员会创建邮件关注，并保存管理链接。",
    guide_text_dbaf2ebdb2d6f272: "{name_a}上的社区委员会",
    guide_text_9439fe6659a056a1: "{name_a}术语表",
    guide_text_fbbb4d3a7f19fd66: "将日期加入您的日历 · {name_a}",
    guide_text_90934486a858f35e: "将一个市政活动加入日历，或订阅整个活动列表，并明确知道自己采用了哪种方式及其可保证什么。",
    guide_text_679ba6001d687a49: "添加单个活动或订阅带日期列表，然后在日历应用中检查结果。",
    guide_text_feb8caca5a9f10ca: "打开Now",
    guide_text_621fa3b9bef5b00f: "阅读土地使用项目 · {name_a}",
    guide_text_dc469d89bd5f156e: "打开土地使用项目，了解下一个行动机构及已知时间，并进入市政府门户查看真实提交文件。",
    guide_text_b23352fad90077be: "检查项目当前阶段、下一项已发布参与机会及官方文件。",
    guide_text_0249073cae431da0: "Zoning Application Portal，由NYC Department of City Planning发布",
    guide_text_39b2ec958868588f: "浏览土地使用项目",
    guide_text_11cf9db750f1d362: "核查关联背后的证据 · {name_a}",
    guide_text_6468cfbf8c0cd948: "打开{name_a}在两条记录间建立的关联凭据，阅读所述内容，并保存可重新打开同一面板的链接。",
    guide_text_9ee797b2017e2770: "检查关联，并复制可重新打开其证据的链接。",
    guide_text_067c4d6457ac8784: "打开本指南使用的关联",
    guide_text_2e438e2d299d89c0: "查看截至某日的记录 · {name_a}",
    guide_text_df41c1bfbc7b25b1: "将机构页面筛选为日期不晚于所选日期的记录，分享结果，并了解此筛选无法告诉您什么。",
    guide_text_db168781332100a3: "按所选日期筛选机构，并分享或清除此视图。",
    guide_text_4bf41e3e5c53d82b: "按类型浏览纽约市公共记录",
    guide_text_b04c5305e9182fb0: "日期与缺失信息的含义",
    guide_text_45ca554361b0518c: "打开按日期筛选的Parks页面",
    guide_text_b386e5f51e61a27c: "收集并导出记录 · {name_a}",
    guide_text_b693f56dc74c7da5: "将真实记录固定在一次调查中、添加备注并导出文件，同时准确了解每份副本保存在哪里、谁能阅读。",
    guide_text_416f08760b272d47: "固定记录、保存备注，并在本地导出和共享副本之间选择。",
    guide_text_efe9f737d26c9c36: "各控件的作用及其输出",
    guide_text_eaffe7e0f637492c: "打开您的调查",
    guide_text_74c74f1cc51aa393: "阅读预算请求及回复 · {name_a}",
    guide_text_b0f275d69c7da30a: "找到您的社区委员会提出的预算请求，按顺序阅读带日期回复，区分回复改变与预算标签改变。",
    guide_text_dfb0fb39ac572a1a: "找到社区委员会的一项预算请求，按顺序阅读已发布回复，并区分回复改变与预算标签改变。",
    guide_text_60bb53de31912624: "日期与缺失信息",
