    guide_text_37429c42a853b0bc: "在{name_a}阅读纽约市公共记录时遇到的术语、标识符和机构的定义，以及各自出现的位置。",
    guide_text_395c88ebbaab3f7e: "在{name_a}阅读记录时遇到的词语，按市政府及本站的用法解释。",
    guide_text_af7e0253b519e305: "参加公务员考试，Department of Citywide Administrative Services",
    guide_text_66b65b6fc9e1f4eb: "控件与输出 · {name_a}",
    guide_text_984b18097f637dce: "{name_a}上的各控件在使用时做什么——搜索、筛选、关注、日历、链接和导出——以及操作后处于什么状态。",
    guide_text_cc0c6126eab81bfe: "查阅常用控件、效果以及生成的文件或链接。",
    guide_text_02129d3d57d1a403: "{name_a}公共端点和上游数据",
