    land_spine_show_all: "显示全部日期（按时间顺序）",
    land_spine_how_summary: "此时间线如何工作",
    land_spine_how_html: "阶段遵循纽约市 ULURP 流程：提交申请、环境审查（CEQR）、预认证通知、认证、社区委员会、区长、城市规划委员会、市议会，以及市长或上诉审查。认证之后，法定审查期限依据 <b>纽约市宪章 §197-c</b>：社区委员会 60 天、区长 30 天、城市规划委员会 60 天、市议会 50 天、市长 5 天（合计不超过 205 天）。这些截止日期是估计值——时钟可暂停、项目可撤回——并非已公布的机构日程。相同的重复提交里程碑会合并为计数与日期范围；每个具体日期仍可在“显示日期”中查看。项目链接只出现一次，指向分区申请门户（ZAP）。",
    land_spine_statutory_deadline_html: "法定截止日期：{stage} 审查须在 {n} 天内结束（市宪章 §197-c）——不晚于 {date}。",
