    site_kicker: "纽约市公共记录，彼此相连",
    back_home_aria: "返回 CityScroll 首页",
    brand_home_aria: "CityScroll 首页",
    back_to_crol: "← 返回 CityScroll",
    home_link: "首页",
    data_page_h1: "数据",
    about_h_what: "这是什么",
    about_p_what_html: "CityScroll 帮助您了解纽约市政府正在发生什么，以及接下来可以做什么。您可以从<b>现在</b>查看紧急日期，从<b>您附近</b>查看本地变化，从<b>关注</b>查看已保存的订阅，或从<b>浏览</b>查看合同和计划、土地使用、会议和表决、职位考试、市有房产出售及规则。使用<b>指南</b>学习如何阅读记录。本站依据市政府官方发布的信息构建，但独立运营，不由纽约市管理或认可。",
    about_h_flags: "标记与背景说明",
    about_h_tax_lien_formula:"Tax lien sale progression",
    about_p_tax_lien_formula_html: "CityScroll 显示处于同一阶段的税收留置权在以往周期中进入最终出售名单的频率。它不会预测房产将被出售或止赎。",
    about_p_flags_intro_html: "采购通知附带两种计算得出的注释。两者都是<b>统计背景，而非结论或指责</b>。标记只意味着「值得仔细看看」。每个公式背后都有正当理由。紧急情况确实会发生。有些市场专业性强，投标人不多。名称匹配也并非完美。此方法遵循两份指南。一份是 <a href=\"https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/\" target=\"_blank\" rel=\"noopener noreferrer\">Open Contracting Partnership 的红旗指南<span class=\"sr-only\"> （在新标签页中打开）</span></a>。另一份是 <a href=\"https://opentender.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">Opentender<span class=\"sr-only\"> （在新标签页中打开）</span></a> 的诚信规则。",
    about_li_flags_html: "<li><b>⚑ 广告窗口过短</b> — 从通知发布到回复截止之间的天数。当天数为 10 天或更少并且少于该机构自身中位数的一半时，我们会标记它。中位数来自该机构最近的 200 条通知。窗口过短会有利于那些已经知道该项工作即将到来的现有承包商。</li><li><b>⚑ 非竞争性方式</b> — 通知表示将在没有完整竞争的情况下选择供应商。这可能是通过谈判达成的交易、单一选定来源、紧急采购或试点项目。有时这是合理的。但知晓总是好的。</li><li><b>⚑ 重复中标（授予合同）</b> — 同一供应商名称在同一机构 90 天内出现在 3 条或更多中标（授予合同）通知上。这可能表明是总括合同下的任务订单，也可能表明偏袒。这个标记只是计数——含义由您来判断。</li><li><b>上下文条</b> — 一笔中标（授予合同）的规模，以该机构过去 12 个月中标（授予合同）的百分位显示（仅当该机构在此期间有 20 笔或更多中标（授予合同）时显示）。它还显示该供应商在同期该机构中标（授予合同）金额中所占的份额。我们使用公布的确切名称。此处不会合并名称的不同写法。</li><li><b>规则通过滞后（估计）</b> — 意见征集截止后，类似 Agency Rules 历史上多久到达 Notice of Adoption。基于 City Record 历史并用右删失，使未完成的立法不会显得过快。当某机构至少有 20 个过往间隔时按机构估计，否则用全市。在规则时间线上显示为虚线 “Estimate” 段，并在摘要邮件中仅在波段变化时显示一行——绝不是已确认日期。完整公式：<a href=\"https://github.com/cityscroll/cityscroll-app/blob/main/docs/formulas/rules-adoption-lag.md\">rules adoption lag</a>.</li>",
    about_p_flags_footer_html: "所有数字都在您查看通知时从 <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">City Record Open Data<span class=\"sr-only\"> （在新标签页中打开）</span></a> 实时获取。这些是<b>公布时</b>的中标（授予合同）。数字可能滞后于合同登记和实际付款。这里没有任何内容说有人做错了事。它只是为您省去了算数的工夫。",
