    session_dismiss: "关闭",
    data_p_lede_html: "The City Record 数据集一览。您的浏览器从 <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> （在新标签页中打开）</span></a> 实时获取总数。服务器上不保存任何内容。这些数字遵循<a href=\"api.html#upstream\">诚实规则</a>。统计数据保留在其所属版块内。可能的录入错误将被排除——金额达到或超过 100 亿美元的记录。占位截止日期不算作真实日期。",
    data_h_sections_html: "记录真正显示的内容 <span class=\"note\">（全部历史，按版块）</span>",
